//! Per-key differential test against triangle.js: random cave-like boards, random B2B/combo state and
//! random `press()` sequences. After every key the engine's return value, piece, `x`, `floor(y)`,
//! rotation and `lastSpin` must match; after the hard drop, the lock result, counters and board.
//!
//! Fixture: `tests/data/key_fuzz.json`, generated by `scratch/m2/fuzz_keys.ts` (see docs/SIM.md).
//! Set `SIM_KEY_FUZZ=<path>` to run an additional (larger) fixture.

use serde_json::Value;
use tetris_sim::board::Board;
use tetris_sim::replay::ColorBoard;
use tetris_sim::{Key, Piece, PlayerState};

fn board_from_rows(rows: &[Value]) -> (Board, ColorBoard) {
    let mut bits = Vec::new();
    let mut garbage = 0u64;
    let mut colors = ColorBoard::default();
    for (y, r) in rows.iter().enumerate() {
        let s = r.as_str().unwrap().as_bytes();
        let mut m = 0u16;
        for (x, &c) in s.iter().enumerate() {
            if c != b'.' {
                m |= 1 << x;
            }
            if c == b'G' {
                garbage |= 1 << y;
            }
            colors.cells[y][x] = c;
        }
        bits.push(m);
    }
    (Board::from_rows(&bits, garbage), colors)
}

fn run_fixture(path: &str) -> usize {
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("{path}: {e}"));
    let cases: Vec<Value> = serde_json::from_str(&text).unwrap();
    for (ci, c) in cases.iter().enumerate() {
        let seed = c["seed"].as_i64().unwrap();
        let mut s = PlayerState::tl(seed);
        let (board, mut colors) = board_from_rows(c["rows"].as_array().unwrap());
        s.board = board;
        s.chain.b2b = c["b2b"].as_i64().unwrap() as i32;
        s.chain.combo = c["combo"].as_i64().unwrap() as i32;
        let keys: Vec<Key> =
            c["keys"].as_array().unwrap().iter().map(|k| Key::from_name(k.as_str().unwrap()).unwrap()).collect();
        let trace = c["trace"].as_array().unwrap();
        let ctx = || format!("case {ci} seed {seed} keys {:?}", c["keys"]);
        for (i, &k) in keys.iter().enumerate() {
            let (moved, out) = s.press_with(k, &mut colors);
            if k == Key::HardDrop {
                let out = out.expect("lock");
                let l = &c["lock"];
                assert_eq!(out.piece.to_char().to_string(), l["piece"].as_str().unwrap(), "{}", ctx());
                assert_eq!(out.lines as i64, l["lines"].as_i64().unwrap(), "lines {}", ctx());
                assert_eq!(out.spin.as_str(), l["spin"].as_str().unwrap(), "spin {}", ctx());
                assert_eq!(out.garbage_cleared as i64, l["garbage_cleared"].as_i64().unwrap(), "gc {}", ctx());
                let raw: Vec<u32> = l["raw"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u32).collect();
                assert_eq!(out.raw.as_slice(), &raw[..], "raw {}", ctx());
                assert_eq!(out.surge as i64, l["surge"].as_i64().unwrap(), "surge {}", ctx());
                assert_eq!(s.chain.b2b as i64, l["b2b"].as_i64().unwrap(), "b2b {}", ctx());
                assert_eq!(s.chain.combo as i64, l["combo"].as_i64().unwrap(), "combo {}", ctx());
                assert_eq!(out.topout, l["topout"].as_bool().unwrap(), "topout {}", ctx());
                let rows: Vec<String> =
                    l["board"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect();
                assert_eq!(colors.rows(), rows, "board {}", ctx());
                assert_eq!(&colors.bits(), s.board.rows(), "bitboard {}", ctx());
                assert!(s.board.check_invariants());
                assert_eq!(s.current().to_char().to_string(), l["next"].as_str().unwrap(), "next {}", ctx());
                break;
            }
            let t = trace[i].as_array().unwrap();
            let exp = (
                t[0].as_i64().unwrap() == 1,
                Piece::from_char(t[1].as_str().unwrap().chars().next().unwrap()).unwrap(),
                t[2].as_i64().unwrap() as i8,
                t[3].as_i64().unwrap() as i8,
                t[4].as_i64().unwrap() as u8,
                t[5].as_str().unwrap(),
            );
            let got = (moved, s.falling.piece, s.falling.x, s.falling.y, s.falling.rot as u8, s.last_spin.as_str());
            assert_eq!(got, exp, "after key {i} ({k:?}) {}", ctx());
        }
    }
    cases.len()
}

#[test]
fn key_fuzz_fixture() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/key_fuzz.json");
    let n = run_fixture(path);
    assert!(n > 0);
    if let Ok(extra) = std::env::var("SIM_KEY_FUZZ") {
        let m = run_fixture(&extra);
        eprintln!("SIM_KEY_FUZZ: {m} extra cases passed");
    }
}
